`timescale 1ns/1ps
// V7: FPGA -> touch screen write-back over uart_tx.
//
// The screen has three pages (home / take a ticket / expression cards). Page navigation
// is done by the screen itself; each page announces itself in its pre-init event with
// the frame 5A 04 <page> chk FF FF FF, so the FPGA knows which idle text fits. Every
// number and decision comes from hospital_app_core; the screen only displays:
//   t0  status / ticket line:  t0.txt="..." FF FF FF
//   q0  queue line:            q0.txt="当前007号  下一位008号  候诊05人" FF FF FF
// Byte content lives in a ROM generated by delivery/multiroom_20261025/tools/touch_status_assets.py; digit
// fields are marker bytes 0x01..0x0D replaced here by ASCII digits from a snapshot taken
// when the message starts, so one message is always self-consistent.
//
// Status priority, highest first: patient rejection (K4..K8; ~1.5 s) > ticket just taken
// (~10 s) > help acknowledged (~5 s after K3) > "sent" (expression page only, while an
// event is queued or playing) > help pending > page idle text. Staff key rejections
// (K1..K3) are not shown to the patient. The queue line is sent whenever the call number
// or the number of tickets changes. Both lines are re-sent PAGE_DELAY frames after a page
// announcement (the page has rendered by then), every REFRESH_FRAMES frames (screen
// power-cycled or reconnected), and after reset. At most one message starts per frame;
// the status line goes first when both are due.
//
// Handshake: the ROM is read synchronously; `present` marks that rom_q holds byte idx.
// tx_valid stays high with that byte until uart_tx accepts it (valid && ready), so no byte
// is skipped or repeated.
module hospital_touch_status #(
    parameter integer HOLD_FRAMES = 90,     // rejection text, ~1.5 s at 60 Hz
    parameter integer ACK_FRAMES = 300,     // "help acknowledged", ~5 s
    parameter integer TICKET_FRAMES = 600,  // "your number ...", ~10 s
    parameter integer REFRESH_FRAMES = 120, // periodic re-send, ~2 s; 0 disables
    parameter integer PAGE_DELAY = 6,       // frames between page announcement and re-send
    parameter integer SEMANTIC_INPUT = 0
)(
    input wire clk, rst,
    input wire frame_start,
    input wire cmd_valid,                   // screen frames from tjc_touch_rx
    input wire [6:0] cmd, arg,
    input wire busy,
    input wire [1:0] help_state,
    input wire [1:0] help_room,             // 10/25: room that confirmed help (marker 0x0E)
    input wire [7:0] accepted_keys,
    input wire [7:0] reject_invalid, reject_duplicate, reject_full, reject_conflict,
    input wire [3:0] queued_events,
    input wire [4:0] call_number, issued_number, waiting_count,
    input wire tx_ready,
    output wire tx_valid,
    output wire [7:0] tx_data,
    output reg [1:0] page,                  // touch page; independent from HDMI patient UI
    input wire command_rejected
);
    // Slot ids; names and values are checked by touch_status_assets.py.
    localparam [3:0] MSG_IDLE_HOME = 4'd0, MSG_SENT = 4'd1, MSG_HELP_PEND = 4'd2,
                     MSG_HELP_ACK = 4'd3, MSG_REJECT = 4'd4, MSG_NOCALL = 4'd5,
                     MSG_TICKET = 4'd6, MSG_TICKET_FULL = 4'd7, MSG_QUEUE = 4'd8,
                     MSG_IDLE_TICKET = 4'd9, MSG_IDLE_EXPR = 4'd10;
    localparam [3:0] MSG_NONE = 4'd15;      // nothing shown yet: forces a write after reset
    localparam integer MSG_SLOTS = 16;
    localparam integer MSG_BYTES = 64;
    localparam [7:0] PATIENT_KEYS = 8'hf8;  // K4..K8 (K8 = take a ticket)
    localparam [6:0] CMD_PAGE = 7'h04;
    localparam [1:0] PAGE_HOME = 2'd0, PAGE_TICKET = 2'd1, PAGE_EXPR = 2'd2;

    reg [7:0] msg_rom [0:MSG_SLOTS*MSG_BYTES-1];
    reg [7:0] len_rom [0:MSG_SLOTS-1];
    initial begin
        $readmemh("touch_status.hex", msg_rom);
        $readmemh("touch_status_len.hex", len_rom);
    end

    wire [7:0] rejects = (reject_invalid | reject_duplicate | reject_full | reject_conflict) & PATIENT_KEYS;
    wire patient_reject = rejects != 0 || (SEMANTIC_INPUT!=0 && command_rejected);
    wire [3:0] reject_msg = reject_invalid[7] ? MSG_TICKET_FULL :
                            reject_invalid[6] ? MSG_NOCALL : MSG_REJECT;
    wire ticket_taken = accepted_keys[7];

    reg [7:0] hold;
    reg [8:0] ack_hold;
    reg [9:0] ticket_hold;
    reg [1:0] help_q, page_pending;
    reg [3:0] hold_msg, want, shown, cur;
    reg [3:0] page_wait;
    reg [4:0] my_ticket, ahead;
    reg [4:0] snap_call, snap_wait;
    reg [9:0] queue_sent;
    reg status_force, queue_force;
    reg expression_sent;
    reg [5:0] idx, len;
    reg sending, present;
    reg [7:0] refresh;
    reg [7:0] rom_q;
    wire ack_edge = help_q == 2'd1 && help_state == 2'd2;
    wire [9:0] queue_key = {call_number, issued_number};

    always @(*) begin
        // The raw pulse/edge are included so a change on the frame_start cycle itself
        // is not shown one frame late.
        if (patient_reject)                         want = reject_msg;
        else if (hold != 0)                         want = hold_msg;
        else if (ticket_taken || ticket_hold != 0)  want = MSG_TICKET;
        else if (ack_edge || ack_hold != 0)         want = MSG_HELP_ACK;
        else if (page == PAGE_EXPR && (SEMANTIC_INPUT==0 || expression_sent) && (busy || queued_events != 0)) want = MSG_SENT;
        else if (help_state == 2'd1)                want = MSG_HELP_PEND;
        else if (page == PAGE_TICKET)               want = MSG_IDLE_TICKET;
        else if (page == PAGE_EXPR)                 want = MSG_IDLE_EXPR;
        else                                        want = MSG_IDLE_HOME;
    end

    // ---- digit fields (ASCII), from values frozen at message start ----
    function [7:0] tens; input [4:0] v; tens = v >= 5'd20 ? "2" : v >= 5'd10 ? "1" : "0"; endfunction
    function [7:0] ones;
        input [4:0] v;
        reg [4:0] o;
        begin
            o = v >= 5'd20 ? v - 5'd20 : v >= 5'd10 ? v - 5'd10 : v;
            ones = 8'h30 + {3'd0, o};
        end
    endfunction
    wire [4:0] snap_next = snap_call + 1'b1;
    wire no_call = snap_call == 0, no_next = snap_wait == 0;
    reg [7:0] field_char;
    always @(*) begin
        case (rom_q[3:0])
            4'd1:  field_char = "0";
            4'd2:  field_char = tens(my_ticket);
            4'd3:  field_char = ones(my_ticket);
            4'd4:  field_char = tens(ahead);
            4'd5:  field_char = ones(ahead);
            4'd6:  field_char = no_call ? "-" : "0";
            4'd7:  field_char = no_call ? "-" : tens(snap_call);
            4'd8:  field_char = no_call ? "-" : ones(snap_call);
            4'd9:  field_char = no_next ? "-" : "0";
            4'd10: field_char = no_next ? "-" : tens(snap_next);
            4'd11: field_char = no_next ? "-" : ones(snap_next);
            4'd12: field_char = tens(snap_wait);
            4'd13: field_char = ones(snap_wait);
            4'd14: field_char = 8'h31 + {6'd0, help_room};
            default: field_char = rom_q;
        endcase
    end
    assign tx_valid = sending && present;
    assign tx_data  = rom_q < 8'h10 ? field_char : rom_q;

    wire refresh_due = REFRESH_FRAMES != 0 && refresh == 0;
    wire status_due = want != shown || status_force;
    wire queue_due = queue_key != queue_sent || queue_force;

    always @(posedge clk) rom_q <= msg_rom[{cur, idx}];

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            expression_sent<=0;
            hold <= 0; hold_msg <= MSG_REJECT; ack_hold <= 0; ticket_hold <= 0; help_q <= 0;
            page <= PAGE_HOME; page_pending <= PAGE_HOME; page_wait <= 0;
            my_ticket <= 0; ahead <= 0; snap_call <= 0; snap_wait <= 0;
            shown <= MSG_NONE; queue_sent <= 10'h3ff; status_force <= 0; queue_force <= 0;
            cur <= 0; sending <= 0; present <= 0; idx <= 0; len <= 0; refresh <= 0;
        end else begin
            // Only a real accepted expression may produce the "sent" label.
            if(accepted_keys[5]) expression_sent<=1;
            else if(!busy && queued_events==0) expression_sent<=0;
            // ---- status bookkeeping ----
            if (patient_reject) begin
                hold <= HOLD_FRAMES; hold_msg <= reject_msg; ticket_hold <= 0;
            end else if (frame_start && hold != 0) hold <= hold - 1'b1;
            if (ticket_taken) begin
                // accepted_keys and issued_number are registered on the same edge.
                // Force a re-send: a second ticket keeps the same message id.
                ticket_hold <= TICKET_FRAMES; status_force <= 1'b1;
                my_ticket <= issued_number;
                ahead <= issued_number - call_number - 1'b1;
            end else if (frame_start && ticket_hold != 0 && !patient_reject) ticket_hold <= ticket_hold - 1'b1;
            help_q <= help_state;
            if (ack_edge) ack_hold <= ACK_FRAMES;
            else if (help_state != 2'd2) ack_hold <= 0;
            else if (frame_start && ack_hold != 0) ack_hold <= ack_hold - 1'b1;

            // ---- page announcements and periodic refresh ----
            if (cmd_valid && cmd == CMD_PAGE && arg <= 7'd2) begin
                page_pending <= arg[1:0]; page_wait <= PAGE_DELAY;
            end else if (frame_start && page_wait != 0) begin
                page_wait <= page_wait - 1'b1;
                if (page_wait == 1) begin page <= page_pending; status_force <= 1; queue_force <= 1; end
            end
            if (frame_start) begin
                if (refresh_due) begin refresh <= REFRESH_FRAMES - 1; status_force <= 1; queue_force <= 1; end
                else if (refresh != 0) refresh <= refresh - 1'b1;
            end

            // ---- transmitter ----
            if (sending) begin
                if (!present) present <= 1'b1;          // rom_q now holds byte idx
                else if (tx_ready) begin
                    present <= 0;
                    if (idx + 1'b1 == len) sending <= 0;
                    else idx <= idx + 1'b1;
                end
            end else if (frame_start && status_due) begin
                cur <= want; shown <= want; status_force <= 0;
                len <= len_rom[want][5:0]; idx <= 0; sending <= 1'b1; present <= 0;
                snap_call <= call_number; snap_wait <= waiting_count;
            end else if (frame_start && queue_due) begin
                cur <= MSG_QUEUE; queue_sent <= queue_key; queue_force <= 0;
                len <= len_rom[MSG_QUEUE][5:0]; idx <= 0; sending <= 1'b1; present <= 0;
                snap_call <= call_number; snap_wait <= waiting_count;
            end
        end
    end
endmodule
